<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Content;use Acorn\SafetyHealthcheck\Database\Schema;
final class SeedContent{
 public static function installIfEmpty():void{global $wpdb;$vt=Schema::table('content_versions');if((int)$wpdb->get_var("SELECT COUNT(*) FROM $vt"))return;$now=current_time('mysql');$wpdb->insert($vt,['version_key'=>'1.0','status'=>'published','created_at'=>$now,'published_at'=>$now,'notes'=>'Approved V1 content']);$v=(int)$wpdb->insert_id;$source=['title'=>'Health and Safety Executive guidance','url'=>'https://www.hse.gov.uk/simple-health-safety/'];foreach(require dirname(__DIR__,2).'/config/questions.php' as $q){$wpdb->insert(Schema::table('questions'),['content_version_id'=>$v,'question_key'=>$q['question_key'],'module_key'=>$q['module_key'],'sort_order'=>$q['sort_order'],'question_text'=>$q['question_text'],'help_text'=>$q['help_text'],'variant_json'=>wp_json_encode(self::variants($q['question_key'])),'applicability_json'=>wp_json_encode(['description'=>$q['applicability']]),'answer_rules_json'=>wp_json_encode(['yes'=>'addressed','partly'=>'review','no'=>$q['no_status'],'not_sure'=>$q['not_sure_status']]),'source_json'=>wp_json_encode($source),'last_reviewed'=>'2026-09-17','next_review'=>'2027-09-17','reviewed_by'=>'Acorn technical reviewer','is_active'=>1]);foreach(['partly','no','not_sure'] as $a){$status=$a==='partly'?'review':$q[$a.'_status'];$identified=$a==='partly'?"Your answer indicates that {$q['subject']} is only partly in place or may not fully reflect the organisation's current circumstances.":($a==='no'?"Your answer indicates that {$q['subject']} may not currently be in place.":"You were not sure whether {$q['subject']} is currently in place.");$next=($a==='not_sure'?'Confirm the current position and who is responsible. Then consider this next step: ':'').$q['next_step'];$tags=self::tags($q['question_key']);$wpdb->insert(Schema::table('recommendations'),['content_version_id'=>$v,'question_key'=>$q['question_key'],'answer_value'=>$a,'jurisdiction'=>'*','finding_status'=>$status,'heading'=>ucfirst($q['subject']),'identified_text'=>$identified,'next_step_text'=>$next,'why_text'=>$q['why'],'good_looks_text'=>$q['good_looks'],'service_tags_json'=>wp_json_encode($tags),'source_json'=>wp_json_encode($source),'sort_rank'=>$q['sort_order']]);}}}
 private static function variants(string $k):array{return $k==='M02_POLICY'?['under_5'=>'Are clear health and safety arrangements in place and kept current?','5_plus'=>'Are clear health and safety arrangements in place, including a current written policy?']:[];}
 private static function tags(string $k):array{if(str_starts_with($k,'F'))return['fire'];if(str_starts_with($k,'L'))return['legionella'];if(str_starts_with($k,'AS'))return['asbestos'];$t=['health_safety'];if(str_starts_with($k,'T'))$t[]='training';return$t;}
}
